(function(){
'use strict';
const E=window.AA012,KEY='aa01_2_beta01_draft_v1',app=document.getElementById('app');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({version:'Vector learning record · 1',schema:1,sessionId:crypto.randomUUID?.()||String(Date.now()),createdAt:new Date().toISOString(),stage:'core',index:0,records:{},followups:[],exposures:[],events:[]});
let storageOK=true,state=fresh(),notice='',error=false;
try{const raw=(window.QuidenceStorage||window.localStorage).getItem(KEY);if(raw){const s=JSON.parse(raw);const ids=new Set([...E.TASKS,...Object.values(E.FOLLOWUPS)].map(t=>t.id));if(s.schema===1&&['core','followup','report'].includes(s.stage)&&s.records&&typeof s.records==='object'&&Array.isArray(s.events)&&Array.isArray(s.exposures)&&Array.isArray(s.followups)&&s.followups.length<=4&&s.followups.every(id=>Object.values(E.FOLLOWUPS).some(t=>t.id===id))&&Number.isInteger(s.index)&&s.index>=0&&Object.entries(s.records).every(([id,r])=>ids.has(id)&&r&&['draft','submitted','skipped'].includes(r.status)&&Array.isArray(r.submissions)&&r.draft&&typeof r.draft==='object')){state=s;const n=s.stage==='followup'?s.followups.length:8;if(s.stage!=='report'&&s.index>=n)state.index=0;}}}catch{storageOK=false;}
function persist(){try{(window.QuidenceStorage||window.localStorage).setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}document.getElementById('storage-status').textContent=storageOK?'Temporary progress stays in this browser.':'Browser saving is unavailable. Export your record before closing.';}
function log(type,data={}){state.events.push({at:new Date().toISOString(),type,...data});}
function tasks(){return state.stage==='followup'?state.followups.map(id=>Object.values(E.FOLLOWUPS).find(t=>t.id===id)):E.TASKS;}
function current(){return tasks()[state.index];}
function draftFor(t){return{values:t.kind==='pair'?['','']:[0,0],choice:null,moved:false,touched:false,explanation:''};}
function record(t){if(!state.records[t.id])state.records[t.id]={status:'draft',draft:draftFor(t),hint:false,submissions:[],enteredAt:new Date().toISOString()};return state.records[t.id];}
function update(part,source){const t=current(),r=record(t);r.draft={...r.draft,...part};if(r.status!=='draft'){r.status='draft';notice='Edited. Submit again to include this answer.';}else notice='';log('answer_changed',{taskId:t.id,source,changes:part});error=false;const status=document.querySelector('.status');if(status){status.textContent=notice;status.classList.remove('error');}persist();}
function numeric(v){return v===''?'':Number(v);}
function submit(){const t=current(),r=record(t);if(!E.valid(t,r.draft)){notice='Complete all required parts. For a graph task, move the point or enter its coordinates first.';error=true;render();return{ok:false,error:notice};}const a=structuredClone(r.draft);const supported=r.hint||state.exposures.some(x=>x.domain===t.domain);const snapshot={at:new Date().toISOString(),answer:a,supported,score:E.score(t,a)};r.submissions.push(snapshot);r.answer=a;r.supported=supported;r.status='submitted';log('answer_submitted',{taskId:t.id,submission:r.submissions.length,supported});notice='Answer saved. You can revise it before continuing.';error=false;persist();render();return{ok:true,taskId:t.id};}
function skip(){const t=current(),r=record(t);r.status='skipped';log('task_skipped',{taskId:t.id});persist();advance();}
function hint(){const t=current(),r=record(t);if(!r.hint){r.hint=true;state.exposures.push({domain:t.domain,taskId:t.id,at:new Date().toISOString()});log('hint_viewed',{taskId:t.id});if(r.status==='submitted'){r.status='draft';notice='Hint viewed. Submit again so the support condition is recorded.';}}persist();render();}
function advance(){const list=tasks(),r=record(current());if(!['submitted','skipped'].includes(r.status)){notice='Submit this answer or choose Skip for now.';error=true;render();return;}notice='';error=false;if(state.index<list.length-1){state.index++;log('task_opened',{taskId:current().id});persist();render(true);return;}const pending=list.findIndex(t=>!['submitted','skipped'].includes(state.records[t.id]?.status));if(pending>=0){state.index=pending;notice='Complete or skip this remaining task before finishing.';persist();render(true);return;}if(state.stage==='core'){const f=E.selectFollowups(state.records);state.followups=f.map(t=>t.id);state.followupTriggers=Object.fromEntries(f.map(t=>[t.id,t.trigger]));if(f.length){state.stage='followup';state.index=0;log('followups_selected',{tasks:f.map(t=>({id:t.id,trigger:t.trigger}))});persist();render(true);return;}}state.stage='report';state.completedAt=new Date().toISOString();log('report_created');persist();render(true);}
function jump(i){const list=tasks();if(!Number.isInteger(i)||i<0||i>=list.length)return;state.index=i;notice='';error=false;log('task_opened',{taskId:current().id});persist();render(true);}
function point(t,r){const a=r.draft.values||[0,0];return t.kind==='coeff'?t.u.map((n,i)=>a[0]*n+a[1]*t.v[i]):['drag','drag-choice'].includes(t.kind)?a:null;}
const coord=a=>'('+a.map(n=>String(n).replace('-', '−')).join(', ')+')';
function graph(t,r){const pos=point(t,r),all=[t.u,t.v,t.target,pos,t.chain&&[t.u[0]+t.v[0],t.u[1]+t.v[1]],t.start&&t.start.map((n,i)=>n+t.u[i])].filter(Boolean);let limit=Math.max(6,Math.ceil(Math.max(...all.flat().map(Math.abs))+1));if(['drag','drag-choice'].includes(t.kind))limit=6;const scale=204/limit,X=n=>240+n*scale,Y=n=>240-n*scale;
let svg=`<svg class="plane" id="plane" viewBox="0 0 480 480" role="img" aria-label="Coordinate plane. ${escape(t.u?'u = '+coord(t.u)+'. ':'')}${escape(t.v?'v = '+coord(t.v)+'. ':'')}${escape(t.target?'Target w = '+coord(t.target)+'. ':'')}${escape(pos?'Your current endpoint is '+coord(pos)+'. ':'')}"><defs><marker id="u-tip" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#087e73"/></marker><marker id="v-tip" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#3658d4"/></marker><marker id="r-tip" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#b8650b"/></marker></defs><rect width="480" height="480" fill="#fafcff"/>`;
const tick=limit>10?2:1;for(let n=-limit;n<=limit;n+=tick){svg+=`<path d="M${X(n)} 36 V444 M36 ${Y(n)} H444" stroke="#e4eaf3" stroke-width="1"/>`;if(n!==0&&n%tick===0)svg+=`<text x="${X(n)}" y="${Y(0)+19}" text-anchor="middle" fill="#687b92" font-size="12">${n}</text><text x="${X(0)-10}" y="${Y(n)+4}" text-anchor="end" fill="#687b92" font-size="12">${n}</text>`;}
svg+=`<path d="M36 240H453 M240 444V27" stroke="#91a3ba" stroke-width="1.6"/><path d="M447 235L453 240L447 245 M235 33L240 27L245 33" fill="none" stroke="#91a3ba"/><text x="457" y="260" font-size="14" fill="#516882">x</text><text x="255" y="28" font-size="14" fill="#516882">y</text><text x="226" y="259" font-size="12" fill="#516882">0</text>`;
if(t.dependent)svg+=`<path d="M${X(-limit/2)} ${Y(-limit)}L${X(limit/2)} ${Y(limit)}" stroke="#087e73" stroke-width="20" opacity=".07"/><text x="45" y="63" fill="#087e73" font-size="14">y = 2x</text>`;
function arrow(a,b,marker,color,label,dash=false){if(a[0]===b[0]&&a[1]===b[1])return;svg+=`<path d="M${X(a[0])} ${Y(a[1])}L${X(b[0])} ${Y(b[1])}" stroke="${color}" stroke-width="3" ${dash?'stroke-dasharray="6 5"':''} marker-end="url(#${marker})"/><text x="${X(b[0])+10}" y="${Y(b[1])-10}" font-size="15" font-weight="600" fill="${color}">${escape(label)}</text>`;}
const start=t.start||[0,0];if(t.u)arrow(start,t.start?start.map((n,i)=>n+t.u[i]):t.u,'u-tip','#087e73',t.id==='v1'?'v':'u');if(t.v)arrow(t.chain?t.u:[0,0],t.chain?t.u.map((n,i)=>n+t.v[i]):t.v,'v-tip','#3658d4','v');
if(t.start){svg+=`<circle cx="${X(start[0])}" cy="${Y(start[1])}" r="4" fill="#142236"/><text x="${X(start[0])-10}" y="${Y(start[1])-10}" text-anchor="end" font-size="13" fill="#52657d">start</text>`;}
if(t.target){svg+=`<circle cx="${X(t.target[0])}" cy="${Y(t.target[1])}" r="10" fill="#fff" stroke="#142236" stroke-width="2"/><path d="M${X(t.target[0])-5} ${Y(t.target[1])}h10 M${X(t.target[0])} ${Y(t.target[1])-5}v10" stroke="#142236"/><text x="${X(t.target[0])+14}" y="${Y(t.target[1])-14}" font-size="14" fill="#142236">w ${coord(t.target)}</text>`;}
if(pos){arrow([0,0],pos,'r-tip','#b8650b',t.kind==='coeff'?'au + bv':'your vector');svg+=`<circle id="dragpoint" cx="${X(pos[0])}" cy="${Y(pos[1])}" r="10" fill="#b8650b" stroke="white" stroke-width="3"/><circle cx="${X(pos[0])}" cy="${Y(pos[1])}" r="20" fill="#b8650b" opacity=".09" pointer-events="none"/>`;}
svg+='</svg>';return svg;}
function controls(t,r){let html='';const a=r.draft;if(['pair','drag','drag-choice'].includes(t.kind)){const labels=t.labels||['Endpoint x','Endpoint y'];html+=`<div class="input-row">${labels.map((l,i)=>`<div class="field"><label for="value-${i}">${escape(l)}</label><input id="value-${i}" data-value="${i}" type="number" step="1" ${t.kind==='pair'?'':'min="-6" max="6"'} value="${escape(a.values[i])}" placeholder="Enter a number" autocomplete="off"></div>`).join('')}</div>`;}
if(t.kind==='coeff'){html+=`<div class="math-panel math">u = ${coord(t.u)}<br>v = ${coord(t.v)}<br>w = ${coord(t.target)}</div><p class="muted" style="font-size:14px">Try coefficients from −3 to 3 in steps of 0.5. Change at least one control before submitting.</p>`;for(let i=0;i<2;i++)html+=`<div class="range-field"><label for="range-${i}">${i===0?'a':'b'}</label><input id="range-${i}" data-range="${i}" type="range" min="-3" max="3" step="0.5" value="${a.values[i]}" aria-label="Coefficient ${i===0?'a':'b'}"><input data-coeff="${i}" type="number" min="-3" max="3" step="0.5" value="${a.values[i]}" aria-label="Enter coefficient ${i===0?'a':'b'}"></div>`;}
if(t.options)html+=`<div class="choices" role="group" aria-label="Answer choices">${t.options.map((o,i)=>`<button class="choice" data-choice="${i}" aria-pressed="${a.choice===i}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${escape(o)}</span></button>`).join('')}</div>`;
html+=`<section class="explanation-workspace"><h3>Explain your thinking (optional)</h3><p class="review-text" style="margin-top:10px">Your explanation is saved for teacher review. It is not automatically graded.</p><p class="review-text">Equations, calculations, or a short explanation are welcome. Your reasoning helps us build a clearer report about what this work shows and what still needs checking. Quidence saves your reasoning for a teacher or tutor to review. A reviewer should judge the mathematics, not grammar, keywords or answer length.</p><label class="sr-only" for="explanation">Explain your thinking</label><textarea id="explanation" placeholder="Show your calculation, formula, or reasoning.">${escape(a.explanation)}</textarea></section>`;return html;}
function render(scroll=false){if(state.stage==='report'){report();if(scroll)window.scrollTo?.(0,0);return;}const t=current(),r=record(t),list=tasks(),f=state.stage==='followup',count=list.filter(x=>['submitted','skipped'].includes(state.records[x.id]?.status)).length,pos=point(t,r);
app.innerHTML=`<div class="topline"><div><span class="eyebrow">${f?'Quick verification':'A foundation for what comes next'}</span><h1>${f?'Look from another angle.':'Start with a vector.'}</h1><p class="muted">${f?'A short check in a new situation. These tasks help fill gaps or clarify mixed evidence.':'Eight short tasks connect movement, coordinates, and equations. Try them independently; a hint is available when you need one.'}</p></div><button class="text-btn" id="reset">Start a new session</button></div><div class="layout"><section class="card task-card" aria-labelledby="task-title"><div class="task-meta"><span class="tag">${f?'CHECK':'TASK'} ${String(state.index+1).padStart(2,'0')} / ${String(list.length).padStart(2,'0')}</span><span>${escape(E.DOMAINS[t.domain])}</span></div><h2 id="task-title">${escape(t.title)}</h2><p>${escape(t.prompt)}</p>${t.math&&t.kind!=='coeff'?`<div class="math-panel math">${escape(t.math).replace(/\n/g,'<br>')}</div>`:''}${controls(t,r)}${r.hint?`<div class="hint">${escape(t.hint)}</div>`:''}<div class="task-actions"><button class="btn primary" id="submit">${r.status==='submitted'?'Save revision':'Submit answer'}</button><button class="btn" id="hint" ${r.hint?'disabled':''}>${r.hint?'Hint viewed':'Show hint'}</button><button class="text-btn" id="skip">Skip for now</button></div><div class="status ${error?'error':''}" role="status">${escape(notice||(r.status==='submitted'?'Answer saved. Feedback comes after the diagnostic.':r.status==='skipped'?'Skipped. You can still submit an answer.':''))}</div></section><section class="card visual-card" aria-label="Vector workspace"><div class="visual-head"><h3>${t.kind==='coeff'?'Build a combination':'The coordinate plane'}</h3><div class="legend">${t.u?'<span><i class="swatch"></i>'+ (t.id==='v1'?'v':'u')+'</span>':''}${t.v?'<span><i class="swatch blue"></i>v</span>':''}${pos?'<span><i class="swatch orange"></i>Your result</span>':''}</div></div><div id="graph">${graph(t,r)}</div>${pos?`<div class="coord-readout"><span>${t.kind==='coeff'?'Current result':'Your endpoint'} <output id="position">${coord(pos)}</output></span>${t.target?`<span>Target <output>${coord(t.target)}</output></span>`:''}</div>`:''}<p class="graph-instruction">${['drag','drag-choice'].includes(t.kind)?'Drag the orange point or click a grid intersection. You can also enter the endpoint coordinates in the answer fields.':t.kind==='coeff'?'The orange arrow shows au + bv. The outlined point is your target. The axes resize when a result moves beyond the current grid.':t.dependent?'The pale band shows the line followed by these two directions.':t.start?'Read the change from the marked start to the arrow tip.':'Each grid step has the value shown on its axis.'}</p></section></div><div class="journey"><span class="journey-label">${f?'Quick checks':'Core tasks'}</span><nav class="steps" aria-label="Task navigation">${list.map((x,i)=>`<button class="step ${i===state.index?'current':''} ${state.records[x.id]?.status==='submitted'?'done':''} ${state.records[x.id]?.status==='skipped'?'skipped':''}" data-jump="${i}" ${i===state.index?'aria-current="step"':''} aria-label="${f?'Check':'Task'} ${i+1}: ${escape(x.title)}, ${escape(state.records[x.id]?.status||'not started')}">${i+1}</button>`).join('')}</nav><span class="progress-meta">${count} / ${list.length} recorded</span><button class="btn dark" id="next">${state.index===list.length-1?(f?'View evidence report':'Finish core tasks'):'Next task'}</button></div><div class="note">${f?'A quick check is selected from missing, incorrect, or conflicting core evidence. Up to four checks are included.':'This is a diagnostic, so answers are saved without revealing correctness yet. A skip means missing evidence. Using a hint is recorded as support, including on later tasks about the same concept.'}</div>`;bind();persist();if(scroll)window.scrollTo?.(0,0);}
function refreshGraph(){const t=current(),r=record(t);document.getElementById('graph').innerHTML=graph(t,r);const el=document.getElementById('position');if(el)el.textContent=coord(point(t,r));bindGraph();}
function bindGraph(){const t=current();if(!['drag','drag-choice'].includes(t.kind))return;const svg=document.getElementById('plane');let dragging=false;
function set(e){const b=svg.getBoundingClientRect();const x=(e.clientX-b.left)*480/b.width,y=(e.clientY-b.top)*480/b.height;const a=[Math.max(-6,Math.min(6,Math.round((x-240)/34))),Math.max(-6,Math.min(6,Math.round((240-y)/34)))];update({values:a,moved:true},'graph');document.querySelectorAll('[data-value]').forEach(el=>el.value=a[Number(el.dataset.value)]);const p=document.getElementById('dragpoint');p.setAttribute('cx',240+a[0]*34);p.setAttribute('cy',240-a[1]*34);document.getElementById('position').textContent=coord(a);}
svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;dragging=true;svg.setPointerCapture?.(e.pointerId);set(e);});svg.addEventListener('pointermove',e=>{if(dragging)set(e);});const end=()=>{if(dragging){dragging=false;refreshGraph();}};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);}
function bind(){document.getElementById('submit').onclick=submit;document.getElementById('skip').onclick=skip;document.getElementById('hint').onclick=hint;document.getElementById('next').onclick=advance;document.getElementById('reset').onclick=resetDialog;document.querySelectorAll('[data-jump]').forEach(el=>el.onclick=()=>jump(Number(el.dataset.jump)));
document.querySelectorAll('[data-value]').forEach(el=>el.oninput=()=>{const t=current(),r=record(t),a=[...r.draft.values],v=numeric(el.value);if(t.kind!=='pair'&&v!==''&&(!Number.isInteger(v)||Math.abs(v)>6)){a[Number(el.dataset.value)]=v;update({values:a,moved:true},'invalid_coordinate_input');notice='Use a whole-number endpoint from −6 to 6.';error=true;document.querySelector('.status').textContent=notice;return;}a[Number(el.dataset.value)]=v;update({values:a,moved:t.kind!=='pair'},'coordinate_input');error=false;if(t.kind!=='pair'&&a.every(x=>typeof x==='number'&&Number.isFinite(x)))refreshGraph();});
document.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{update({choice:Number(el.dataset.choice)},'choice');error=false;render();});
function coefficient(el,i){const v=Number(el.value);if(el.value===''||!Number.isFinite(v)||v < -3||v>3||Math.abs(v*2-Math.round(v*2))>.001){const a=[...record(current()).draft.values];a[i]=el.value===''?'':v;update({values:a,touched:true},'invalid_coefficient_input');notice='Choose a coefficient from −3 to 3 in steps of 0.5.';error=true;document.querySelector('.status').textContent=notice;return;}const a=[...record(current()).draft.values];a[i]=v;update({values:a,touched:true},'coefficient');error=false;document.querySelectorAll(`[data-range="${i}"],[data-coeff="${i}"]`).forEach(x=>{if(x!==el)x.value=v;});refreshGraph();}
document.querySelectorAll('[data-range]').forEach(el=>el.oninput=()=>coefficient(el,Number(el.dataset.range)));document.querySelectorAll('[data-coeff]').forEach(el=>el.oninput=()=>coefficient(el,Number(el.dataset.coeff)));document.getElementById('explanation').oninput=e=>{update({explanation:e.target.value},'explanation');};bindGraph();}
function allTasks(){return[...E.TASKS,...state.followups.map(id=>Object.values(E.FOLLOWUPS).find(t=>t.id===id))];}
function model(){return Object.keys(E.DOMAINS).map(d=>E.evidence(state.records,d));}
const pill=s=>s==='Independent evidence'?'independent':s==='Supported evidence'||s==='Mixed support conditions'?'supported':s==='Conflicting evidence'||s==='Needs another check'?'conflicting':'';
function reportData(){return{...structuredClone(state),model:model(),assessmentNotes:['Task-level observations; not validated mastery probabilities.','Open explanations require human review.','Responses from different parts of the same task are related, not independent repeated evidence.','Time and interaction traces do not establish AI use, effort, or intent.','Learning records stay in this browser. Accounts and cloud sync are paused.'],taskVersions:allTasks().map(t=>({id:t.id,version:'0.1',domain:t.domain,dimension:t.dimension,title:t.title,prompt:t.prompt,solution:t.solution}))};}
function readableAnswer(t,a){if(!a)return'No current submitted answer';const parts=[];if(a.values&&t.kind!=='choice')parts.push((t.kind==='coeff'?'a, b = ':'Components = ')+coord(a.values));if(t.options&&Number.isInteger(a.choice))parts.push('Choice: '+t.options[a.choice]);return parts.join('\n');}
function report(){const ts=allTasks(),m=model(),submitted=ts.filter(t=>state.records[t.id]?.status==='submitted').length,skipped=ts.filter(t=>state.records[t.id]?.status==='skipped').length,supported=ts.filter(t=>state.records[t.id]?.status==='submitted'&&state.records[t.id]?.supported).length;app.innerHTML=`<div class="report-heading"><div><span class="eyebrow">Your learning snapshot</span><h1>Evidence, with room for questions.</h1><p class="muted">What this session showed across calculations, pictures, and meaning. A correct answer is an observation, not a final mastery judgment.</p></div><div class="report-actions"><button class="btn" id="export-md">Export readable report</button><button class="btn" id="export-json">Export full record</button><button class="btn dark" id="reset">New session</button></div></div><div class="metrics"><div class="metric"><span class="value">${submitted} / ${ts.length}</span><span class="label">Tasks answered</span></div><div class="metric"><span class="value">${supported}</span><span class="label">Answers with prior support</span></div><div class="metric"><span class="value">${skipped}</span><span class="label">Skipped · missing evidence</span></div></div><div class="report-grid">${m.map(e=>`<section class="evidence-card"><span class="pill ${pill(e.state)}">${escape(e.state)}</span><h3>${escape(e.name)}</h3>${e.observations.length?`<ul>${e.observations.map(o=>`<li>${escape(o.dimension)} · ${o.correct?'matched':'did not match'} · ${o.supported?'after support':'without recorded support'} <span class="muted">(${escape(o.id)})</span></li>`).join('')}</ul>`:'<p>No submitted answer available for this concept.</p>'}<p class="muted">${e.state==='Conflicting evidence'?'Results disagree across representations. Recheck the specific differences before drawing a conclusion.':e.state==='Independent evidence'?'Successful responses without recorded hints. More varied tasks are needed before claiming mastery.':e.state==='Supported evidence'?'Success followed a hint on this concept. Try a fresh task without support next.':e.state==='Mixed support conditions'?'This concept has evidence both before and after support. Keep those conditions separate.':e.state==='Missing evidence'?'Try a short task before making a judgment. A skip does not show a misconception.':'Start from a worked example, then check again with a different representation.'}</p></section>`).join('')}<section class="evidence-card"><span class="pill">Teacher review</span><h3>Explanation & transfer</h3><p>${ts.filter(t=>state.records[t.id]?.answer?.explanation?.trim()).length} explanations saved for review. Their meaning has not been automatically graded.</p><p class="muted">Choices and numeric answers are checked with fixed rules. The system does not infer effort or AI use from speed or clicks.</p></section></div><details open><summary>Next steps: build one connection at a time</summary><div class="practice-grid" style="margin-top:18px"><div class="practice-card"><span class="eyebrow">01 · Movement</span><h3>Translate an arrow</h3><p>Draw the same vector from two starting points. Compare endpoint minus start.</p></div><div class="practice-card"><span class="eyebrow">02 · Combination</span><h3>Use the tip-to-tail view</h3><p>Add two movements, then draw the direct arrow from the origin to the result.</p></div><div class="practice-card"><span class="eyebrow">03 · Reachability</span><h3>Ask what can be reached</h3><p>Compare two arrows on one line with two arrows pointing in independent directions.</p></div><div class="practice-card"><span class="eyebrow">04 · Equations</span><h3>Read the components</h3><p>Write a horizontal equation and a vertical equation for one vector combination.</p></div></div></details><details><summary>Inspect answers, revisions, and worked explanations</summary>${ts.map(t=>{const r=state.records[t.id];return`<article class="record"><span class="tag">${escape(t.id)} · ${escape(t.dimension)}</span><h3 style="margin-top:10px">${escape(t.title)}</h3><p>${escape(t.prompt)}</p><p>${r?.status==='skipped'?'Skipped · missing evidence':escape(readableAnswer(t,r?.answer))}</p>${r?.answer?.explanation?`<p>Explanation for review: <span data-no-translate>${escape(r.answer.explanation)}</span></p>`:''}<p class="muted">${r?.submissions.length||0} submission(s) · ${r?.hint?'hint viewed':'no task hint'}${state.followupTriggers?.[t.id]?' · Follow-up reason: '+escape(state.followupTriggers[t.id]):''}</p>${r?.submissions.length?`<details><summary>Submission history</summary>${r.submissions.map((s,i)=>`<p>${i+1}. ${escape(readableAnswer(t,s.answer))}<br>${s.supported?'After recorded support':'Without recorded support'} · ${escape(s.at)}</p>${s.answer.explanation?`<p>Explanation: <span data-no-translate>${escape(s.answer.explanation)}</span></p>`:''}`).join('')}</details>`:''}<p class="feedback">${escape(t.solution)}</p></article>`;}).join('')}</details><div class="note">These activities use original tasks and transparent scoring rules. This snapshot is not a validated proficiency score. Your current record stays in this browser; export it to keep a copy. Cross-device records and long-term learning memory are not available yet.</div>`;document.getElementById('reset').onclick=resetDialog;document.getElementById('export-json').onclick=()=>download('Quidence_Vector_Record.json',JSON.stringify(reportData(),null,2),'application/json');document.getElementById('export-md').onclick=()=>download('Quidence_Vector_Report.md',markdown(),'text/markdown');persist();if(window.QuidenceReportStore){const saved=window.QuidenceReportStore.save('ab01',{...reportData(),reportKind:'vector-diagnostic',markdown:markdown()},state.sessionId);window.QuidenceReportStore.appendNotice(app,saved);}}
function markdown(){const lines=['# Linear Algebra Foundations','## Learning snapshot','',`Session: ${state.sessionId}`,`Created: ${state.createdAt}`,`Completed: ${state.completedAt}`,'','Task-level observations, not a validated mastery score. Open explanations require teacher review.',''];for(const e of model()){lines.push(`## ${e.name}`,e.state,'',...e.observations.map(o=>`- ${o.dimension} (${o.id}): ${o.correct?'matched':'did not match'}; ${o.supported?'after support':'without recorded support'}`),'');}lines.push('## Answer record','');for(const t of allTasks()){const r=state.records[t.id];lines.push(`### ${t.id} · ${t.title}`,t.prompt,'',r?.status==='skipped'?'Skipped: missing evidence':readableAnswer(t,r?.answer),'',`Hint: ${r?.hint?'viewed':'not viewed'}. Submissions: ${r?.submissions.length||0}.`,r?.answer?.explanation?'Explanation (human review):\n'+window.QuidenceReportTools.quote(r.answer.explanation):'No written explanation supplied.',`Worked explanation: ${t.solution}`,'');for(const [i,s]of(r?.submissions||[]).entries())lines.push(`Submission ${i+1} (${s.at}; ${s.supported?'supported':'no recorded support'}): ${readableAnswer(t,s.answer)}`,'');}lines.push('## Limits','',...reportData().assessmentNotes.map(n=>'- '+n));return lines.join('\n');}
function download(name,body,type){if(type==='text/markdown') body=window.QuidenceI18n?.markdown(body)||body;const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function resetDialog(){const d=document.createElement('dialog');d.innerHTML='<h2>Start a new session?</h2><p>This replaces the current browser record. Export your report first if you want to keep it.</p><div class="report-actions"><button class="btn" id="cancel-reset">Keep this session</button><button class="btn primary" id="confirm-reset">Start new session</button></div>';document.body.appendChild(d);d.querySelector('#cancel-reset').onclick=()=>{d.close();d.remove();};d.querySelector('#confirm-reset').onclick=()=>{state=fresh();notice='';error=false;persist();d.close();d.remove();render(true);};d.addEventListener('cancel',()=>d.remove());d.showModal();}
// Expose the same actions to supported page agents. No separate scoring or hidden mutation path.
if(document.modelContext?.registerTool){const tools=[{name:'read_diagnostic_state',title:'Read diagnostic state',description:'Read the current task and saved diagnostic observations.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('Expected an empty object.');return{stage:state.stage,index:state.index,taskId:state.stage==='report'?null:current().id,model:model()};}},{name:'stage_diagnostic_answer',title:'Stage a diagnostic answer',description:'Fill the current answer without submitting. Does not navigate or reveal correctness.',inputSchema:{type:'object',properties:{values:{type:'array',items:{type:'number'},minItems:2,maxItems:2},choice:{type:'integer',minimum:0},explanation:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(state.stage==='report')throw new Error('Session is finished.');if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['values','choice','explanation'].includes(k)))throw new Error('Invalid answer input.');const t=current(),next={...record(t).draft,...input,moved:true,touched:true};if(!E.valid(t,next)||input.explanation!==undefined&&typeof input.explanation!=='string')throw new Error('Complete answer required.');if(['drag','drag-choice'].includes(t.kind)&&next.values.some(v=>!Number.isInteger(v)||Math.abs(v)>6))throw new Error('Endpoint must be a grid point from −6 to 6.');if(t.kind==='coeff'&&next.values.some(v=>Math.abs(v)>3||v*2!==Math.round(v*2)))throw new Error('Coefficients must be in steps of 0.5 from −3 to 3.');update(next,'page_agent');render();return{staged:true,taskId:t.id};}},{name:'submit_diagnostic_answer',title:'Submit diagnostic answer',description:'Save the staged answer for the current task. Does not advance to the next task.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length||state.stage==='report')throw new Error('Cannot submit this input.');return submit();}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t)).catch(()=>{});}catch{}}}
render();
})();

